-- TPC-DS Test_Query Query 440
-- Based on: query56.tpl (medium)
-- Variation: 100

with ss as ( select i_item_id,sum(ss_ext_sales_price) total_sales from store_sales, date_dim, customer_address, item where i_item_id in (select i_item_id from item where i_color in ('COLOR.1','COLOR.4','COLOR.1')) and     ss_item_sk              = i_item_sk and     ss_sold_date_sk         = d_date_sk and     d_year                  = 2006 and     d_moy                   = 14 and     ss_addr_sk              = ca_address_sk and     ca_gmt_offset           = 69 group by i_item_id), cs as ( select i_item_id,sum(cs_ext_sales_price) total_sales from catalog_sales, date_dim, customer_address, item where i_item_id               in (select i_item_id from item where i_color in ('COLOR.3','COLOR.1','COLOR.4')) and     cs_item_sk              = i_item_sk and     cs_sold_date_sk         = d_date_sk and     d_year                  = 1919 and     d_moy                   = 8 and     cs_bill_addr_sk         = ca_address_sk and     ca_gmt_offset           = 42 group by i_item_id), ws as ( select i_item_id,sum(ws_ext_sales_price) total_sales from web_sales, date_dim, customer_address, item where i_item_id               in (select i_item_id from item where i_color in ('COLOR.1','COLOR.1','COLOR.5')) and     ws_item_sk              = i_item_sk and     ws_sold_date_sk         = d_date_sk and     d_year                  = 2064 and     d_moy                   = 10 and     ws_bill_addr_sk         = ca_address_sk and     ca_gmt_offset           = 72 group by i_item_id)  select  i_item_id ,sum(total_sales) total_sales from  (select * from ss union all select * from cs union all select * from ws) tmp1 group by i_item_id order by total_sales, i_item_id limit 102;
